import ExcelJS from "exceljs";
import FileSaver from "file-saver";
import { FormData, BBNTData } from "../types";

export async function exportToExcel(formData: FormData) {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('BM02 - Tờ Trình');

  // Set default font
  worksheet.properties.defaultRowHeight = 20;

  // Define columns
  worksheet.columns = [
    { header: 'STT', key: 'stt', width: 8 },
    { header: 'Tên Vật tư / Thiết bị', key: 'name', width: 40 },
    { header: 'ĐVT', key: 'unit', width: 10 },
    { header: 'Số lượng', key: 'quantity', width: 15 },
    { header: 'Đơn giá', key: 'unitPrice', width: 15 },
    { header: 'Thành tiền', key: 'total', width: 20 },
    { header: 'Ghi chú', key: 'note', width: 25 },
  ];

  // Title Section
  worksheet.mergeCells('A1:G1');
  const titleCell = worksheet.getCell('A1');
  titleCell.value = "TỜ TRÌNH PHÊ DUYỆT KINH PHÍ";
  titleCell.font = { name: 'Times New Roman', size: 16, bold: true };
  titleCell.alignment = { horizontal: 'center' };

  worksheet.mergeCells('A2:G2');
  const subTitleCell = worksheet.getCell('A2');
  subTitleCell.value = formData.title;
  subTitleCell.font = { name: 'Times New Roman', size: 14, bold: true, italic: true };
  subTitleCell.alignment = { horizontal: 'center' };

  worksheet.mergeCells('A3:G3');
  const dateCell = worksheet.getCell('A3');
  dateCell.value = `${formData.location}, ${formData.date}`;
  dateCell.font = { name: 'Times New Roman', size: 12, italic: true };
  dateCell.alignment = { horizontal: 'right' };

  // Empty row
  worksheet.addRow([]);

  // Table Header Styling
  const headerRow = worksheet.getRow(5);
  headerRow.values = ['STT', 'Tên Vật tư / Thiết bị', 'ĐVT', 'Số lượng', 'Đơn giá', 'Thành tiền', 'Ghi chú'];
  headerRow.font = { name: 'Times New Roman', bold: true };
  headerRow.eachCell((cell) => {
    cell.border = {
      top: { style: 'thin' },
      left: { style: 'thin' },
      bottom: { style: 'thin' },
      right: { style: 'thin' }
    };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFE0E0E0' }
    };
  });

  // Data Rows
  let currentRowIndex = 6;
  formData.items.forEach((item) => {
    const row = worksheet.addRow({
      stt: item.stt,
      name: item.name,
      unit: item.unit,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      total: item.total,
      note: item.note
    });

    row.eachCell((cell, colNumber) => {
      cell.font = { name: 'Times New Roman' };
      cell.border = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' }
      };

      // Number formatting for Qty, Price, Total
      if (colNumber === 4) cell.numFmt = '#,##0.00';
      if (colNumber === 5 || colNumber === 6) cell.numFmt = '#,##0';
    });
    currentRowIndex++;
  });

  // Total Row
  const totalRow = worksheet.addRow(['', 'Tổng cộng', '', '', '', formData.totalAmount, '']);
  totalRow.getCell(2).font = { name: 'Times New Roman', bold: true };
  totalRow.getCell(2).alignment = { horizontal: 'center' };
  worksheet.mergeCells(`A${currentRowIndex}:A${currentRowIndex}`); // Empty STT
  worksheet.mergeCells(`B${currentRowIndex}:E${currentRowIndex}`); // Label merge

  const totalCell = totalRow.getCell(6);
  totalCell.font = { name: 'Times New Roman', bold: true };
  totalCell.numFmt = '#,##0';

  totalRow.eachCell((cell) => {
    cell.border = {
      top: { style: 'thin' },
      left: { style: 'thin' },
      bottom: { style: 'thin' },
      right: { style: 'thin' }
    };
  });

  // Write and Save
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
  const fileName = formData.originalFileName ? `${formData.originalFileName}_BM02.xlsx` : `To_Trinh_${Date.now()}_BM02.xlsx`;
  FileSaver.saveAs(blob, fileName);
}

export async function exportBBNTToExcel(bbntData: BBNTData) {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('BM03.2 - BBNT');

  worksheet.properties.defaultRowHeight = 20;

  worksheet.columns = [
    { header: 'STT', key: 'stt', width: 8 },
    { header: 'Diễn giải', key: 'description', width: 45 },
    { header: 'ĐVT', key: 'unit', width: 10 },
    { header: 'SL Yêu cầu', key: 'requestedQty', width: 15 },
    { header: 'SL Nghiệm thu', key: 'acceptedQty', width: 15 },
    { header: 'Ghi chú', key: 'note', width: 25 },
  ];

  // Header Info
  worksheet.mergeCells('A1:F1');
  const titleCell = worksheet.getCell('A1');
  titleCell.value = "BIÊN BẢN NGHIỆM THU VÀ BÀN GIAO";
  titleCell.font = { name: 'Times New Roman', size: 16, bold: true, color: { argb: 'FF2B579A' } };
  titleCell.alignment = { horizontal: 'center' };

  worksheet.mergeCells('A2:F2');
  worksheet.getCell('A2').value = `Số: ${bbntData.docNumber}`;
  worksheet.getCell('A2').alignment = { horizontal: 'center' };

  // Project Info
  worksheet.mergeCells('A4:F4');
  worksheet.getCell('A4').value = `Công trình: ${bbntData.project}`;
  worksheet.getCell('A4').font = { bold: true };

  worksheet.mergeCells('A5:F5');
  worksheet.getCell('A5').value = `Hạng mục: ${bbntData.category}`;

  worksheet.mergeCells('A6:F6');
  worksheet.getCell('A6').value = `Bên Giao: ${bbntData.senderCompany}`;

  worksheet.mergeCells('A7:F7');
  worksheet.getCell('A7').value = `Bên Nhận: ${bbntData.receiverCompany}`;

  // Start Table at Row 9
  const headerRow = worksheet.getRow(9);
  headerRow.values = ['STT', 'Diễn giải', 'ĐVT', 'SL Yêu cầu', 'SL Nghiệm thu', 'Ghi chú'];
  headerRow.font = { name: 'Times New Roman', bold: true };
  headerRow.eachCell((cell) => {
    cell.border = {
      top: { style: 'thin' },
      left: { style: 'thin' },
      bottom: { style: 'thin' },
      right: { style: 'thin' }
    };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFE0E0E0' }
    };
  });

  // Data Rows
  bbntData.items.forEach((item) => {
    const row = worksheet.addRow({
      stt: item.stt,
      description: item.description,
      unit: item.unit,
      requestedQty: item.requestedQty,
      acceptedQty: item.acceptedQty,
      note: item.note || ''
    });

    row.eachCell((cell, colNumber) => {
      cell.font = { name: 'Times New Roman' };
      cell.border = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' }
      };

      if (colNumber === 4 || colNumber === 5) cell.numFmt = '#,##0.00';
    });
  });

  // Footer Signatures (Basic Layout)
  worksheet.addRow([]);
  worksheet.addRow([]);
  const sigHeaderRow = worksheet.addRow(['', 'ĐẠI DIỆN BÊN GIAO', '', '', 'ĐẠI DIỆN BÊN NHẬN', '']);
  sigHeaderRow.font = { bold: true };
  sigHeaderRow.getCell(2).alignment = { horizontal: 'center' };
  sigHeaderRow.getCell(5).alignment = { horizontal: 'center' };

  worksheet.mergeCells(`B${sigHeaderRow.number}:C${sigHeaderRow.number}`);
  worksheet.mergeCells(`E${sigHeaderRow.number}:F${sigHeaderRow.number}`);

  // Write and Save
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
  const fileName = bbntData.originalFileName ? `${bbntData.originalFileName}_BM03.2.xlsx` : `BBNT_${Date.now()}_BM03.2.xlsx`;
  FileSaver.saveAs(blob, fileName);
}

