        )}

        {activeTab === 'BM02' ? (
          <div className="bg-white shadow-2xl rounded-sm border border-slate-300 mx-auto max-w-[800px] document-font p-12 md:p-16 space-y-8 min-h-[1100px] text-black relative">
            <div className="grid grid-cols-[1.2fr_3fr_1fr] border border-black">
              <div className="border-r border-black p-4 flex items-center justify-center">
                <div className="bti-logo-container">
                  <div className="bti-box"><span className="bti-letter">B</span></div>
                  <div className="bti-box"><span className="bti-letter">T</span></div>
                  <div className="bti-box"><span className="bti-letter">I</span></div>
