import ExcelJS from "exceljs";
import FileSaver from "file-saver";
import { FormData, BBNTData } from "../types";

const BORDER_STYLE: Partial<ExcelJS.Borders> = {
  top: { style: 'thin' },
  left: { style: 'thin' },
  bottom: { style: 'thin' },
  right: { style: 'thin' }
};

const FONT_NORMAL = { name: 'Times New Roman', size: 11 };
const FONT_BOLD = { name: 'Times New Roman', size: 11, bold: true };
const FONT_ITALIC = { name: 'Times New Roman', size: 11, italic: true };

export async function exportToExcel(formData: FormData) {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('BM02 - Tờ Trình');

  // Page Setup
  worksheet.pageSetup.margins = {
    left: 0.7, right: 0.7,
    top: 0.75, bottom: 0.75,
    header: 0.3, footer: 0.3
  };

  // Define columns width approximation
  worksheet.columns = [
    { key: 'col1', width: 5 },  // STT
    { key: 'col2', width: 30 }, // Name
    { key: 'col3', width: 8 },  // Unit
    { key: 'col4', width: 10 }, // Qty
    { key: 'col5', width: 15 }, // Price
    { key: 'col6', width: 15 }, // Total
    { key: 'col7', width: 20 }, // Note
  ];

  let rowIndex = 1;

  // 1. Header
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const row1 = worksheet.getCell(`A${rowIndex}`);
  row1.value = "TỜ TRÌNH";
  row1.font = { name: 'Times New Roman', size: 16, bold: true };
  row1.alignment = { horizontal: 'center' };
  rowIndex++;

  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const row2 = worksheet.getCell(`A${rowIndex}`);
  row2.value = formData.title;
  row2.font = { name: 'Times New Roman', size: 13, bold: true };
  row2.alignment = { horizontal: 'center', wrapText: true };
  row2.getRow().height = 30; 
  rowIndex++;

  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const row3 = worksheet.getCell(`A${rowIndex}`);
  row3.value = `Số: ${formData.docNumber}`;
  row3.font = FONT_BOLD;
  row3.alignment = { horizontal: 'center' };
  rowIndex++;

  // Date
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowDate = worksheet.getCell(`A${rowIndex}`);
  rowDate.value = `${formData.location}, ${formData.date}`;
  rowDate.font = FONT_ITALIC;
  rowDate.alignment = { horizontal: 'right' };
  rowIndex++;

  // Spacing
  rowIndex++;

  // Kính gửi
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowKG = worksheet.getCell(`A${rowIndex}`);
  rowKG.value = "Kính gửi:";
  rowKG.font = FONT_BOLD;
  rowIndex++;

  formData.recipients.forEach(r => {
    worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
    const cell = worksheet.getCell(`A${rowIndex}`);
    cell.value = `- ${r}`;
    cell.font = FONT_NORMAL;
    cell.alignment = { indent: 1 };
    rowIndex++;
  });

  // Grounds
  formData.grounds.forEach(g => {
    worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
    const cell = worksheet.getCell(`A${rowIndex}`);
    cell.value = `- ${g}`;
    cell.font = FONT_NORMAL;
    cell.alignment = { wrapText: true };
    rowIndex++;
  });

  rowIndex++; // Space

  // Intro text
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowIntro = worksheet.getCell(`A${rowIndex}`);
  rowIntro.value = `Phòng kỹ thuật kính trình Hội đồng thành viên và BGĐ Công ty TNHH MTV Thương Mại Becamex ${formData.title.replace(/^V\/v:\s*/i, "")}, nội dung sau:`;
  rowIntro.font = FONT_NORMAL;
  rowIntro.alignment = { wrapText: true };
  rowIntro.getRow().height = 30; 
  rowIndex++;

  rowIndex++;

  // Section 1
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowSec1 = worksheet.getCell(`A${rowIndex}`);
  rowSec1.value = "1/ Mua vật tư, thiết bị:";
  rowSec1.font = { ...FONT_BOLD, underline: true };
  rowIndex++;

  // Table Header
  const headerValues = ['STT', 'Vật tư / Thiết bị', 'ĐVT', 'Số lượng', 'Đơn giá', 'Thành tiền', 'Ghi chú'];
  const rowHeader = worksheet.getRow(rowIndex);
  rowHeader.values = headerValues;
  rowHeader.font = FONT_BOLD;
  rowHeader.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };

  for(let c=1; c<=7; c++) {
    worksheet.getCell(rowIndex, c).border = BORDER_STYLE;
    worksheet.getCell(rowIndex, c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0E0E0' } };
  }
  rowIndex++;

  // Items
  formData.items.forEach((item) => {
    const row = worksheet.getRow(rowIndex);
    row.values = [
      item.stt,
      item.name,
      item.unit,
      item.quantity,
      item.unitPrice,
      item.total,
      item.note
    ];
    row.font = FONT_NORMAL;
    // Formatting
    row.getCell(1).alignment = { horizontal: 'center' }; // STT
    row.getCell(2).alignment = { wrapText: true }; // Name
    row.getCell(3).alignment = { horizontal: 'center' }; // Unit
    row.getCell(4).numFmt = '#,##0.00'; // Qty
    row.getCell(5).numFmt = '#,##0'; // Price
    row.getCell(6).numFmt = '#,##0'; // Total
    row.getCell(7).alignment = { wrapText: true }; // Note

    for(let c=1; c<=7; c++) {
      row.getCell(c).border = BORDER_STYLE;
    }
    rowIndex++;
  });

  // Total Row
  const totalRow = worksheet.getRow(rowIndex);
  totalRow.getCell(1).value = null;
  worksheet.mergeCells(`A${rowIndex}:A${rowIndex}`); 

  worksheet.mergeCells(`B${rowIndex}:E${rowIndex}`);
  const labelTotal = totalRow.getCell(2);
  labelTotal.value = "Tổng cộng (đã bao gồm thuế GTGT)";
  labelTotal.font = FONT_BOLD;
  labelTotal.alignment = { horizontal: 'center' };

  const valTotal = totalRow.getCell(6);
  valTotal.value = formData.totalAmount;
  valTotal.numFmt = '#,##0';
  valTotal.font = FONT_BOLD;

  const noteTotal = totalRow.getCell(7);
  noteTotal.value = "";

  for(let c=1; c<=7; c++) {
    totalRow.getCell(c).border = BORDER_STYLE;
  }
  rowIndex++;

  rowIndex++;

  // Section 2
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowSec2 = worksheet.getCell(`A${rowIndex}`);
  rowSec2.value = "2/ Xác nhận của bộ phận QLVT (nếu có):";
  rowSec2.font = { ...FONT_BOLD, underline: true };
  rowIndex++;

  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  const rowNote = worksheet.getCell(`A${rowIndex}`);
  rowNote.value = "(Khối lượng còn trong kho được ghi tại cột ghi chú ở bảng trên)";
  rowNote.font = FONT_ITALIC;
  rowIndex++;

  // Dotted lines
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  worksheet.getCell(`A${rowIndex}`).value = ".......................................................................................................................................................................................................";
  rowIndex++;
  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  worksheet.getCell(`A${rowIndex}`).value = ".......................................................................................................................................................................................................";
  rowIndex++;

  worksheet.mergeCells(`A${rowIndex}:G${rowIndex}`);
  worksheet.getCell(`A${rowIndex}`).value = "Trân trọng!";
  rowIndex++;
  rowIndex++;

  // Signatures BM02
  // Row 1 titles
  const sigRow1 = worksheet.getRow(rowIndex);
  sigRow1.values = ["Phòng Kế toán", "", "Phòng Kỹ thuật", "", "", "Người lập", ""];
  // Merge: A-B (1-2), C-E (3-5), F-G (6-7) to balance widths (30, 33, 35)
  worksheet.mergeCells(`A${rowIndex}:B${rowIndex}`);
  worksheet.mergeCells(`C${rowIndex}:E${rowIndex}`);
  worksheet.mergeCells(`F${rowIndex}:G${rowIndex}`);

  [1, 3, 6].forEach(c => {
    const cell = sigRow1.getCell(c);
    cell.font = FONT_BOLD;
    cell.alignment = { horizontal: 'center' };
  });
  rowIndex += 4; // Space for signing

  // Row 1 names
  const sigName1 = worksheet.getRow(rowIndex);
  worksheet.mergeCells(`A${rowIndex}:B${rowIndex}`);
  worksheet.mergeCells(`C${rowIndex}:E${rowIndex}`);
  worksheet.mergeCells(`F${rowIndex}:G${rowIndex}`);
  sigName1.getCell(1).value = "Lương Thị Ngọc Trinh";
  sigName1.getCell(3).value = "Nguyễn Xuân Nam";
  sigName1.getCell(6).value = "Trần Nam Anh";
  [1, 3, 6].forEach(c => {
    const cell = sigName1.getCell(c);
    cell.font = FONT_BOLD;
    cell.alignment = { horizontal: 'center' };
  });

  rowIndex += 2;

